#include "world_helper.hpp"
static std::vector<float> read(const char*p,size_t limit){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()<=0||f.tellg()%4||size_t(f.tellg())>limit)throw std::runtime_error("input size");std::vector<float>v(size_t(f.tellg())/4);f.seekg(0);f.read((char*)v.data(),v.size()*4);for(float x:v)if(!std::isfinite(x))throw std::runtime_error("nonfinite");return v;}
int main(int argc,char**argv){try{if(argc!=6)throw std::runtime_error("SHADERS ATLAS VERTICES OUT depth|top");std::string mode=argv[5];if(mode!="depth"&&mode!="top")throw std::runtime_error("mode");gAlways=mode=="top";auto atlas=read(argv[2],65*49*4),verts=read(argv[3],12*20);if(atlas.size()!=65*49||verts.size()!=60)throw std::runtime_error("dimensions");for(float x:atlas)if(x<0||x>1)throw std::runtime_error("coverage");for(size_t i=0;i<verts.size();i+=5){if(std::abs(verts[i])>4||std::abs(verts[i+1])>4||verts[i+2]<=.125f||verts[i+2]>=9||verts[i+3]<0||verts[i+3]>1||verts[i+4]<0||verts[i+4]>1)throw std::runtime_error("positive-w/coordinate budget");}
 std::filesystem::path out=argv[4];if(!std::filesystem::create_directory(out))throw std::runtime_error("existing output");{TextLab lab(argv[1]);lab.worldBuffer=lab.buffers.size();lab.buffers.push_back(lab.buffer(verts.size()*4,VK_BUFFER_USAGE_VERTEX_BUFFER_BIT));memcpy(lab.buffers[lab.worldBuffer].map,verts.data(),verts.size()*4);auto result=lab.draw(atlas,{.1f,.2f,.3f,.5f},{.9f,.5f,.2f,.75f});save(out/"color.f32",result[0]);save(out/"velocity.f32",result[1]);save(out/"id.f32",result[2]);std::vector<float>d(3185);memcpy(d.data(),lab.buffers[lab.readDepth].map,d.size()*4);save(out/"depth.f32",d);std::cout<<"NEAR_CLIP_PASS validation_enabled="<<lab.validation<<"\n";}if(validationErrors)throw std::runtime_error("validation");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
